import React from 'react';
import { ComponentMeta, ComponentStory } from '@storybook/react';
import { Badge } from '../..';

const BADGE_COLORS = [
  'blue',
  'purple',
  'gray',
  'yellow',
  'green',
  'orange',
  'red',
  'info',
] as const;

export default {
  title: 'Feedback/Badge/Status',
  component: Badge.Status,
  argTypes: {
    label: {
      description: 'Assing a text label to the badge',
      defaultValue: 'Label',
    },
    color: {
      description: 'Define one of the pre-defined color to badge background',
      defaultValue: 'blue',
    },
    type: {
      description: 'Specify how the badge component should behave',
      defaultValue: 'default',
    },
    disabled: {
      description: 'Boolean value defining if is disabled or not',
      defaultValue: 'false',
    },
  },
  parameters: {
    docs: {
      description: {
        component:
          'How to install: `yarn add @hexa-ui/components`<br><br>How to import: `import { Badge } from "@hexa-ui/components"`<br><br> How to use: `Badge.Status` or destructure it `{ Status } = Badge`',
      },
    },
  },
} as ComponentMeta<typeof Badge.Status>;

const Template: ComponentStory<typeof Badge.Status> = (args) => <Badge.Status {...args} />;

export const Default = Template.bind({});

export const WithDefaultColors = (): JSX.Element => (
  <div style={{ display: 'flex' }}>
    {BADGE_COLORS.map((color) => (
      <div key={color} style={{ margin: '0.25rem' }}>
        <Badge.Status color={color} label={color} />
      </div>
    ))}
  </div>
);

export const WithInteractiveColors = (): JSX.Element => (
  <div style={{ display: 'flex' }}>
    {BADGE_COLORS.map((color) => (
      <div key={color} style={{ margin: '0.25rem' }}>
        <Badge.Status
          onClick={() => console.log('Clicked on color', color)}
          type="interactive"
          color={color}
          label="Interactive"
        />
      </div>
    ))}
  </div>
);

export const WithDisabled = (): JSX.Element => (
  <Badge.Status label="Disabled" disabled color="orange" />
);
